begin;
create table public.website_platform_settings(id boolean primary key default true check(id),base_domain text,managed_subdomain_tls boolean not null default false,allowed_embeds jsonb not null default '["www.youtube-nocookie.com","www.google.com","www.openstreetmap.org"]',disabled_components jsonb not null default '[]',updated_at timestamptz not null default now());
create table public.website_plan_limits(plan_id uuid primary key references public.plans(id),configuration jsonb not null default '{}' check(jsonb_typeof(configuration)='object' and octet_length(configuration::text)<=8192));
create table private.website_build_keys(key_id text primary key,secret bytea not null check(octet_length(secret)>=32),active boolean not null default true);
create function private.website_config(org uuid) returns jsonb language sql stable security definer set search_path='' as $$
select '{"sites":3,"pages":50,"storage_bytes":52428800,"forms":true,"custom_domain":false,"custom_code":false,"developer_mode":false,"analytics":false,"integrations":false}'::jsonb||coalesce((select l.configuration from public.organizations o join public.website_plan_limits l on l.plan_id=o.plan_id where o.id=org),'{}')||coalesce((select e.configuration from public.organization_entitlements e join public.modules m on m.id=e.module_id where e.organization_id=org and m.key='website' and e.enabled and e.valid_from<=now() and (e.valid_until is null or e.valid_until>now()) order by case e.source when 'manual' then 0 when 'addon' then 1 else 2 end,e.updated_at desc limit 1),'{}');$$;
create table public.websites(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),name text not null check(length(trim(name)) between 1 and 160),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) between 3 and 63),status text not null default 'draft' check(status in ('draft','published','unpublished','suspended','archived')),published_version_id uuid,document jsonb not null check(jsonb_typeof(document)='object' and octet_length(document::text)<=2000000),unique(id,organization_id));
create table public.website_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),website_id uuid not null,user_id uuid not null,active boolean not null default true,unique(website_id,user_id),foreign key(organization_id,website_id) references public.websites(organization_id,id),foreign key(organization_id,user_id) references public.organization_memberships(organization_id,user_id));
create table public.website_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),website_id uuid not null,sequence integer not null check(sequence>0),summary text not null check(length(summary)<=500),snapshot jsonb not null check(octet_length(snapshot::text)<=2500000),restored_from uuid,unique(website_id,sequence),foreign key(organization_id,website_id) references public.websites(organization_id,id),foreign key(organization_id,restored_from) references public.website_versions(organization_id,id));
create table public.website_domains(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),website_id uuid not null,hostname text not null check(hostname=lower(hostname) and length(hostname)<=253 and hostname ~ '^[a-z0-9][a-z0-9.-]+[a-z0-9]$'),kind text not null check(kind in ('subdomain','custom')),status text not null default 'pending' check(status in ('pending','verifying','verified','active','failed','suspended','removed')),challenge text not null default encode(extensions.gen_random_bytes(32),'hex'),verified_at timestamptz,last_checked_at timestamptz,failure_reason text not null default '',tls_status text not null default 'pending' check(tls_status in ('pending','ready','failed')),foreign key(organization_id,website_id) references public.websites(organization_id,id));
create table public.website_assets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),website_id uuid not null,name text not null check(length(name) between 1 and 200),mime text not null check(mime in ('image/webp','application/pdf','video/mp4')),bytes integer not null check(bytes between 1 and 10485760),width integer,height integer,alt text not null default '' check(length(alt)<=500),digest text not null check(digest ~ '^[0-9a-f]{64}$'),status text not null default 'ready' check(status in ('ready','archived')),foreign key(organization_id,website_id) references public.websites(organization_id,id));
create table public.website_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),version integer not null default 1 check(version>0),created_by uuid references public.profiles(id) default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),website_id uuid not null,action text not null check(length(action)<=100),metadata jsonb not null default '{}' check(octet_length(metadata::text)<=2000),foreign key(organization_id,website_id) references public.websites(organization_id,id));
alter table public.websites add foreign key(organization_id,published_version_id) references public.website_versions(organization_id,id);
create unique index website_domain_live_unique on public.website_domains(hostname) where status<>'removed';
create table private.website_asset_data(asset_id uuid primary key references public.website_assets(id),data bytea not null);
create table private.website_form_limits(website_id uuid not null references public.websites(id),bucket timestamptz not null,hits integer not null,primary key(website_id,bucket));
create table private.website_metrics(website_id uuid not null references public.websites(id),day date not null,kind text not null,hits bigint not null default 0,primary key(website_id,day,kind));
create function private.website_access(org uuid,permission text,site uuid default null) returns boolean language sql stable security definer set search_path='' as $$
select private.has_permission(org,permission) and private.entitled(org,'website') and (site is null or exists(select 1 from public.websites w where w.organization_id=org and w.id=site and (private.has_permission(org,'website.scope.manage') or exists(select 1 from public.website_members m where m.organization_id=org and m.website_id=w.id and m.user_id=auth.uid() and m.active))));$$;
create function private.website_require(org uuid,permission text,site uuid default null) returns void language plpgsql security definer set search_path='' as $$begin perform 1 from public.organizations where id=org for update;if not private.website_access(org,permission,site) then raise exception 'Unavailable website operation' using errcode='42501';end if;end$$;
create function private.website_event(org uuid,site uuid,event text,details jsonb default '{}') returns void language plpgsql security definer set search_path='' as $$begin insert into public.website_events(organization_id,website_id,action,metadata) values(org,site,event,details);insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),org,event,'websites',site::text);end$$;
alter table public.websites enable row level security;alter table public.websites force row level security;revoke all on public.websites from public,anon,authenticated;grant select on public.websites to authenticated;
create policy website_read on public.websites for select to authenticated using(private.website_access(organization_id,'website.view',id));
create index websites_tenant on public.websites(organization_id,created_at desc,id);
create trigger touch_updated_at before update on public.websites for each row execute function private.touch_updated_at();
alter table public.website_members enable row level security;alter table public.website_members force row level security;revoke all on public.website_members from public,anon,authenticated;grant select on public.website_members to authenticated;
create policy website_read on public.website_members for select to authenticated using(private.website_access(organization_id,'website.view',website_id));
create index website_members_tenant on public.website_members(organization_id,created_at desc,id);
create trigger touch_updated_at before update on public.website_members for each row execute function private.touch_updated_at();
alter table public.website_versions enable row level security;alter table public.website_versions force row level security;revoke all on public.website_versions from public,anon,authenticated;grant select on public.website_versions to authenticated;
create policy website_read on public.website_versions for select to authenticated using(private.website_access(organization_id,'website.view',website_id));
create index website_versions_tenant on public.website_versions(organization_id,created_at desc,id);
create trigger website_immutable before update or delete on public.website_versions for each row execute function private.ops_immutable();
alter table public.website_domains enable row level security;alter table public.website_domains force row level security;revoke all on public.website_domains from public,anon,authenticated;grant select on public.website_domains to authenticated;
create policy website_read on public.website_domains for select to authenticated using(private.website_access(organization_id,'website.domain.view',website_id));
create index website_domains_tenant on public.website_domains(organization_id,created_at desc,id);
create trigger touch_updated_at before update on public.website_domains for each row execute function private.touch_updated_at();
alter table public.website_assets enable row level security;alter table public.website_assets force row level security;revoke all on public.website_assets from public,anon,authenticated;grant select on public.website_assets to authenticated;
create policy website_read on public.website_assets for select to authenticated using(private.website_access(organization_id,'website.media.manage',website_id));
create index website_assets_tenant on public.website_assets(organization_id,created_at desc,id);
create trigger touch_updated_at before update on public.website_assets for each row execute function private.touch_updated_at();
alter table public.website_events enable row level security;alter table public.website_events force row level security;revoke all on public.website_events from public,anon,authenticated;grant select on public.website_events to authenticated;
create policy website_read on public.website_events for select to authenticated using(private.website_access(organization_id,'website.view',website_id));
create index website_events_tenant on public.website_events(organization_id,created_at desc,id);
create trigger website_immutable before update or delete on public.website_events for each row execute function private.ops_immutable();
alter table public.website_platform_settings enable row level security;alter table public.website_platform_settings force row level security;revoke all on public.website_platform_settings from public,anon,authenticated;grant select on public.website_platform_settings to authenticated;create policy platform_website_read on public.website_platform_settings for select to authenticated using(private.has_platform_permission('platform.catalog.view'));
alter table public.website_plan_limits enable row level security;alter table public.website_plan_limits force row level security;revoke all on public.website_plan_limits from public,anon,authenticated;grant select on public.website_plan_limits to authenticated;create policy platform_website_read on public.website_plan_limits for select to authenticated using(private.has_platform_permission('platform.catalog.view'));
revoke all on private.website_build_keys,private.website_asset_data,private.website_form_limits,private.website_metrics from public,anon,authenticated;
revoke all on function private.website_access(uuid,text,uuid),private.website_require(uuid,text,uuid),private.website_config(uuid),private.website_event(uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function private.website_access(uuid,text,uuid) to authenticated;
commit;
